from __future__ import annotations
from typing import Callable, FrozenSet, Iterable, Sequence, TypeVar
T = TypeVar("T")
U = TypeVar("U")
def extension_failures(a: Sequence[T], b: Sequence[U], leq_a: Callable[[T,T],bool], leq_b: Callable[[U,U],bool], rel: Callable[[T,U],bool]) -> list[tuple[T,T,U]]:
    return [(a0,a1,b0) for a0 in a for a1 in a if leq_a(a0,a1)
            for b0 in b if rel(a0,b0)
            if not any(leq_b(b0,b1) and rel(a1,b1) for b1 in b)]

